עֲלֵיכֶם שָׁלוֹם.

סִמָּן טוֹב וּמַזָּל טוֹב יִהְיֶה לָנוּ וּלְכָל יִשְׂרָאֵל אָמֵן:
סִמָּן טוֹב וּמַזָּל טוֹב יִהְיֶה לָנוּ וּלְכָל יִשְׂרָאֵל אָמֵן:
סִמָּן טוֹב וּמַזָּל טוֹב יִהְיֶה לָנוּ וּלְכָל יִשְׂרָאֵל אָמֵן: 

קוֹל דּודִי הִנֵּה זֶה בָּא מְדַלֵּג עַל הֶהָרִים מְקַפֵּץ עַל הַגְּבָעוֹת דּוֹמֶה דוֹדִי לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים הִנֵּה זֶה עוֹמֵד אַחַר כָּתְלֵנוּ מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים:

שִׁיר לַמַּעֲלוֹת, אֶשָּׂא עֵינַי אֶל הֶהָרִים, מֵאַיִן יָבֹא עֶזְרִי; עֶזְרִי מֵעִם י~הוה, עֹשֵׂה שָׁמַיִם וָאָרֶץ; אַל יִתֵּן לַמּוֹט רַגְלֶךָ, אַל יָנוּם שֹׁמְרֶךָ; הִנֵּה לֹא יָנוּם וְלֹא יִישָׁן שׁוֹמֵר יִשְׂרָאֵל; י~הוה שֹׁמְרֶךָ, י~הוה צִלְּךָ עַל יַד יְמִינֶךָ; יוֹמָם הַשֶּׁמֶשׁ לֹא יַכֶּכָּה, וְיָרֵחַ בַּלָּיְלָה; י~הוה יִשְׁמָרְךָ מִכָּל רָע, יִשְׁמֹר אֶת נַפְשֶׁךָ; י~הוה יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ, מֵעַתָּה וְעַד עוֹלָם;

הַלְלוּי~ָהּ הַלְלוּ אֵ~ל בְּקָדְשׁוֹ, הַלְלוּהוּ בִּרְקִיעַ עֻזּוֹ; הַלְלוּהוּ בִגְבוּרֹתָיו, הַלְלוּהוּ כְּרֹב גֻּדְלוֹ; הַלְלוּהוּ בְּתֵקַע שׁוֹפָר, הַלְלוּהוּ בְּנֵבֶל וְכִנּוֹר; הַלְלוּהוּ בְתֹף וּמָחוֹל, הַלְלוּהוּ בְּמִנִּים וְעוּגָב; הַלְלוּהוּ בְצִלְצְלֵי שָׁמַע, הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה; כֹּל הַנְּשָׁמָה תְּהַלֵּל יָ~הּ, הַלְלוּיָ~הּ;

תָּנָא דְבֵי רַבִּי יִשְׁמָעֵאל אִלְמָלֵי לֹא זָכוּ יִשְׂרָאֵל אֶלָּא לְהַקְבִּיל פְּנֵי אֲבִיהֶם שֶׁבַּשָׁמַיִם פַּעַם אַחַת בַּחֹדֶשׁ דַּיָם. אָמַר אַבַּיֵי הִלְכָּךְ צָרִיךְ לְמֵימְרָא מְעוּמָד: מִי זֹאת עולָה מִן הַמִּדְבָּר מִתְרַפֶּקֶת עַל דּוֹדָהּ: וִיהִי רָצוֹן מִלְּפָנֶיךָ י~הוה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי לְמַלֹּאת פְּגִימַת הַלְּבָנָה וְלֹא יִהְיֶה בָּהּ שׁוּם מִעוּט. וִיהִי אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וּכְאוֹר שִׁבְעַת יְמֵי בְרֵאשִׁית כְּמו שֶׁהָיְתָה קוֹדֶם מִעוּטָהּ. שֶׁנֶּאֱמַר אֶת שְׁנֵי הַמְּארוֹת הַגְּדוֹלִים: וְיִתְקַיֶם בָּנוּ מִקְרָא שֶׁכָּתוּב וּבִקְשׁוּ אֶת י~הוה אֱלֹהֵיהֶם וְאֵת דָּוִיד מַלְכָּם. אָמֵן: 

לַמְנַצֵּחַ בִּנְגִינֹת מִזְמוֹר שִׁיר; אֱ~לֹהִים יְחָנֵּנוּ וִיבָרְכֵנוּ, יָאֵר פָּנָיו אִתָּנוּ סֶלָה; לָדַעַת בָּאָרֶץ דַּרְכֶּךָ, בְּכָל-גּוֹיִם יְשׁוּעָתֶךָ; יוֹדוּךָ עַמִּים אֱ~לֹהִים, יוֹדוּךָ עַמִּים כֻּלָּם; יִשְׂמְחוּ וִירַנְּנוּ לְאֻמִּים כִּי-תִשְׁפֹּט עַמִּים מִישֹׁר, וּלְאֻמִּים בָּאָרֶץ תַּנְחֵם סֶלָה; יוֹדוּךָ עַמִּים אֱ~לֹהִים, יוֹדוּךָ עַמִּים כֻּלָּם; אֶרֶץ נָתְנָה יְבוּלָהּ, יְבָרְכֵנוּ אֱ~לֹהִים אֱ~לֹהֵינוּ; יְבָרְכֵנוּ אֱ~לֹהִים, וְיִירְאוּ אוֹתוֹ כָּל-אַפְסֵי-אָרֶץ;
